def fires(b):
    return b.heights[0] == 3 and b.grid[2][0] == 2

def level(b):
    if not fires(b):
        return 0
    n = sum(1 for r in range(3) if b.grid[r][0] == 2)
    lv = 3 + 2 * n
    if b.last_col == 0:
        lv += 1
    return min(lv, 9)

def ncol0(b):
    return sum(1 for r in range(3) if b.grid[r][0] == 2)

def fires(b):
    return b.heights[0] == 3 and b.grid[2][0] == 2 and ncol0(b) >= 2

def level(b):
    if b.heights[0] != 3 or b.grid[2][0] != 2:
        return 0
    n = ncol0(b)
    if n == 3:
        lv = 8
    elif n == 2:
        lv = 5
    else:
        lv = 3
    if b.heights[1] >= 1:
        lv += 1
    return min(lv, 9)

def core(b):
    return b.heights[0] == 3 and b.grid[2][0] == 2

def ncol0(b):
    return sum(1 for r in range(3) if b.grid[r][0] == 2)

def fires(b):
    return core(b) and (b.last_col == 0 or ncol0(b) >= 2)

def level(b):
    if not core(b):
        return 0
    n = ncol0(b)
    lv = 1 + n
    if b.last_col == 0:
        lv += 3
    if n == 3:
        lv += 2
    return min(lv, 9)
